    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the most common cause of Failure to Thrive (FTT) in the pediatric population?', '["Malabsorption", "Inadequate caloric intake", "Genetic disorders", "Increased metabolic demand"]', 1, 'Inadequate caloric intake, primarily due to non-organic or psychosocial factors (e.g., poor feeding technique, poverty), is the #1 cause of FTT.'),
    (v_topic_id, '2: In a child with Failure to Thrive (FTT) due to malnutrition, what is the typical pattern of growth deceleration?', '["Head circumference drops first, then weight, then length", "Weight drops first, then length, then head circumference", "Length drops first, then weight, then head circumference", "All three drop simultaneously"]', 1, 'Weight is affected first, followed by height/length. Brain growth (head circumference) is spared until late, severe malnutrition occurs.'),
    (v_topic_id, '3: Which parameter on the growth chart is most strictly defined as Failure to Thrive?', '["Weight for age below the 10th percentile", "Weight for age that crosses two major percentile lines downwards", "Height for age below the 5th percentile", "BMI between the 5th and 85th percentile"]', 1, 'Crossing two major percentiles on the growth chart over time is a classic and definitive hallmark of FTT.'),
    (v_topic_id, '4: A 9-month-old infant presents with FTT. The mother dilutes the formula to make it last longer due to financial struggles. This is an example of:', '["Non-organic FTT", "Organic FTT", "Malabsorption", "Increased metabolic demand"]', 0, 'Non-organic FTT is caused by environmental, psychosocial, or economic factors rather than a primary medical illness.'),
    (v_topic_id, '5: Which of the following conditions is an "organic" cause of FTT due to increased metabolic demand?', '["Cleft palate", "Celiac disease", "Congenital heart disease", "Gastroesophageal reflux"]', 2, 'CHD causes increased work of breathing and tachycardia, significantly increasing caloric requirements.'),
    (v_topic_id, '6: A 2-year-old child presents with FTT, chronic diarrhea, and abdominal distension. Removing wheat from the diet improves symptoms. Diagnosis?', '["Cystic Fibrosis", "Celiac Disease", "Cow''s milk protein allergy", "Giardiasis"]', 1, 'Celiac disease is a classic cause of malabsorptive FTT triggered by gluten (wheat, rye, barley).'),
    (v_topic_id, '7: A 6-month-old presents with FTT, recurrent greasy stools, and a chronic cough. What is the best initial diagnostic test?', '["Sweat chloride test", "Tissue transglutaminase IgA", "Upper endoscopy", "Stool culture"]', 0, 'Cystic fibrosis presents with malabsorption (pancreatic insufficiency) and recurrent respiratory infections.'),
    (v_topic_id, '8: What is the most appropriate initial management for an infant with non-organic FTT?', '["Immediate hospitalization and NG tube feeding", "Extensive metabolic and genetic testing", "Dietary counseling and frequent outpatient weight checks", "Prescribe an appetite stimulant"]', 2, 'Close outpatient follow-up, optimizing caloric density, and parent education are the first steps.'),
    (v_topic_id, '9: A child with severe malnutrition is admitted and started on rapid high-calorie feeds. On day 2, the child develops weakness, arrhythmias, and seizures. Diagnosis?', '["Sepsis", "Refeeding syndrome", "Hypercalcemia", "Hypoglycemia"]', 1, 'Refeeding syndrome occurs when rapid carbohydrate intake causes a massive insulin surge, driving electrolytes intracellularly.'),
    (v_topic_id, '10: Which electrolyte abnormality is the hallmark of Refeeding Syndrome?', '["Hyperkalemia", "Severe hypophosphatemia", "Hypernatremia", "Hypermagnesemia"]', 1, 'Hypophosphatemia is the classic and most dangerous hallmark, leading to ATP depletion, weakness, and arrhythmias.'),
    (v_topic_id, '11: What is the defining characteristic of "Kwashiorkor"?', '["Severe generalized wasting without edema", "Protein malnutrition with adequate or near-adequate total calories, characterized by edema", "Vitamin C deficiency", "Vitamin D deficiency"]', 1, 'Kwashiorkor classically presents with generalized edema (due to hypoalbuminemia) and a "flaky paint" dermatosis.'),
    (v_topic_id, '12: What is the defining characteristic of "Marasmus"?', '["Edema and fatty liver", "Non-edematous severe total caloric malnutrition (wasting of fat and muscle)", "Night blindness", "Bowed legs"]', 1, 'Marasmus is a state of severe starvation with an emaciated appearance ("skin and bones") without edema.'),
    (v_topic_id, '13: A child with Kwashiorkor typically has an enlarged abdomen. This is primarily due to:', '["Ascites and fatty liver (hepatomegaly)", "Severe constipation", "Intestinal parasites", "Splenomegaly"]', 0, 'Decreased apolipoprotein synthesis leads to fat accumulation in the liver, while hypoalbuminemia causes ascites/edema.'),
    (v_topic_id, '14: A breastfed 6-month-old infant who does not receive any supplements presents with bowing of the legs (genu varum) and widened wrists. What is the deficient nutrient?', '["Vitamin A", "Vitamin C", "Vitamin D", "Iron"]', 2, 'Breast milk is deficient in Vitamin D. Lack of supplementation leads to nutritional Rickets.'),
    (v_topic_id, '15: What is the recommended daily dose of Vitamin D supplementation for exclusively breastfed infants?', '["100 IU", "200 IU", "400 IU", "800 IU"]', 2, 'The AAP recommends 400 IU/day of Vitamin D starting within the first few days of life.'),
    (v_topic_id, '16: Which of the following radiographic findings is classic for Rickets?', '["Pencil-thin cortices and multiple fractures", "Cupping and fraying of the metaphyseal ends of long bones", "Subperiosteal hemorrhage", "Lead lines at the metaphyses"]', 1, 'Failure of osteoid calcification leads to widened, cupped, and frayed metaphyses on X-ray.'),
    (v_topic_id, '17: A child presents with the "rachitic rosary." What does this describe?', '["A rash on the chest", "Enlargement of the costochondral junctions", "A chain of enlarged cervical lymph nodes", "Beaded appearance of the spine"]', 1, 'Expansion of the costochondral junctions in the rib cage is a classic physical finding in Rickets.'),
    (v_topic_id, '18: Craniotabes (a soft, ping-pong ball sensation of the skull) is an early sign of which nutritional deficiency?', '["Vitamin A", "Vitamin B1", "Vitamin C", "Vitamin D"]', 3, 'Craniotabes is a classic early sign of Rickets due to thinning of the outer table of the skull.'),
    (v_topic_id, '19: A 4-year-old immigrant child presents with night blindness and dry, thickened conjunctivae with silvery-gray triangular spots (Bitot spots). What is the deficient nutrient?', '["Vitamin A", "Vitamin B12", "Zinc", "Copper"]', 0, 'Vitamin A deficiency is a leading cause of preventable blindness worldwide (xerophthalmia).'),
    (v_topic_id, '20: Severe Vitamin A deficiency can lead to which irreversible eye complication?', '["Cataracts", "Keratomalacia (corneal ulceration and necrosis)", "Glaucoma", "Retinal detachment"]', 1, 'Keratomalacia is a late and devastating complication of Vitamin A deficiency.'),
    (v_topic_id, '21: Which viral infection significantly depletes Vitamin A stores and is treated with Vitamin A supplementation in developing countries to reduce mortality?', '["Varicella", "Measles (Rubeola)", "Mumps", "Rubella"]', 1, 'The WHO recommends Vitamin A for children with measles, as it significantly reduces morbidity and mortality.'),
    (v_topic_id, '22: Excess intake of Vitamin A can lead to toxicity. What is a classic sign of acute Vitamin A toxicity?', '["Alopecia and hepatomegaly", "Pseudotumor cerebri (increased intracranial pressure)", "Peripheral neuropathy", "Hemolytic anemia"]', 1, 'Acute toxicity presents with nausea, vomiting, and bulging fontanelle/papilledema due to increased ICP.'),
    (v_topic_id, '23: A toddler fed exclusively on goat''s milk presents with pallor, fatigue, and a macrocytic anemia. What is the most likely nutritional deficiency?', '["Iron", "Folate (Vitamin B9)", "Vitamin B12", "Vitamin C"]', 1, 'Goat''s milk is notoriously deficient in folate (and iron), leading to megaloblastic anemia.'),
    (v_topic_id, '24: A strict vegan mother exclusively breastfeeds her 9-month-old infant. The infant develops developmental regression, hypotonia, and macrocytic anemia. Deficient nutrient?', '["Vitamin B1 (Thiamine)", "Vitamin B6 (Pyridoxine)", "Vitamin B12 (Cobalamin)", "Iron"]', 2, 'Vitamin B12 is found exclusively in animal products. Deficiency causes neurologic damage and megaloblastic anemia.'),
    (v_topic_id, '25: A child presents with bleeding gums, petechiae, coiled "corkscrew" hairs, and poor wound healing. They refuse to eat fruits or vegetables. Deficient nutrient?', '["Vitamin K", "Vitamin C (Ascorbic Acid)", "Zinc", "Vitamin A"]', 1, 'Scurvy (Vitamin C deficiency) leads to defective collagen synthesis (impaired hydroxylation of proline/lysine).'),
    (v_topic_id, '26: What is a classic radiographic finding in a child with Scurvy?', '["Cupping of metaphyses", "Subperiosteal hemorrhage and the ''''Frankel line'''' (dense zone of provisional calcification)", "Multiple bone cysts", "Osteophytes"]', 1, 'Subperiosteal bleeding causes extreme bone pain (the child may assume a "frog-leg" posture to avoid moving).'),
    (v_topic_id, '27: A neonate is born at home and does not receive routine newborn care. On day 3, the infant develops severe gastrointestinal and intracranial bleeding. Deficient nutrient?', '["Vitamin A", "Vitamin E", "Vitamin K", "Iron"]', 2, 'Vitamin K prophylaxis is given at birth to prevent Hemorrhagic Disease of the Newborn (Vitamin K Deficiency Bleeding).'),
    (v_topic_id, '28: Which coagulation factors are dependent on Vitamin K?', '["Factors I, II, V, X", "Factors II, VII, IX, X, Protein C, and Protein S", "Factors VIII, IX, XI", "Factors XI, XII"]', 1, 'Vitamin K is required for the gamma-carboxylation of these factors.'),
    (v_topic_id, '29: A premature infant is fed a formula high in polyunsaturated fatty acids but lacking a specific vitamin. The infant develops hemolytic anemia and peripheral neuropathy. Deficient nutrient?', '["Vitamin A", "Vitamin D", "Vitamin E", "Vitamin K"]', 2, 'Vitamin E is an antioxidant; deficiency makes RBC membranes susceptible to oxidative stress and hemolysis.'),
    (v_topic_id, '30: A child in a developing country with a diet consisting solely of polished rice presents with heart failure, edema, and peripheral neuropathy. What is the disease?', '["Pellagra", "Beriberi", "Scurvy", "Rickets"]', 1, 'Beriberi is caused by Vitamin B1 (Thiamine) deficiency. "Wet" beriberi affects the heart; "dry" affects the nerves.'),
    (v_topic_id, '31: Wernicke-Korsakoff syndrome, though rare in children (unless on TPN without supplementation), is caused by a deficiency of:', '["Vitamin B1 (Thiamine)", "Vitamin B2 (Riboflavin)", "Vitamin B3 (Niacin)", "Vitamin B6 (Pyridoxine)"]', 0, 'It presents with the triad of ophthalmoplegia, ataxia, and confusion/confabulation.'),
    (v_topic_id, '32: A child presents with angular cheilitis (fissures at the corners of the mouth), glossitis, and seborrheic dermatitis. Deficient nutrient?', '["Vitamin B1 (Thiamine)", "Vitamin B2 (Riboflavin)", "Vitamin B3 (Niacin)", "Vitamin C"]', 1, 'Riboflavin deficiency classically causes mucosal and skin lesions.'),
    (v_topic_id, '33: A child on a corn-based diet presents with the "3 Ds": Dermatitis (in sun-exposed areas), Diarrhea, and Dementia. What is the disease?', '["Pellagra", "Beriberi", "Acrodermatitis enteropathica", "Scurvy"]', 0, 'Pellagra is caused by Vitamin B3 (Niacin) deficiency.'),
    (v_topic_id, '34: Niacin can be synthesized endogenously from which amino acid?', '["Phenylalanine", "Tyrosine", "Tryptophan", "Methionine"]', 2, 'Tryptophan is a precursor to niacin. Hartnup disease (decreased tryptophan absorption) can cause pellagra-like symptoms.'),
    (v_topic_id, '35: A child treated with Isoniazid (INH) for tuberculosis develops peripheral neuropathy and seizures. Which vitamin supplement should have been provided?', '["Vitamin B1", "Vitamin B3", "Vitamin B6 (Pyridoxine)", "Vitamin B12"]', 2, 'INH competitively inhibits pyridoxine, leading to neurotoxicity.'),
    (v_topic_id, '36: A 6-month-old infant is exclusively breastfed. The mother asks when she should introduce a cup and start weaning from the bottle/breast. Recommendation?', '["Introduce cup at 6 months, aim to wean from bottle by 12-18 months", "Wait until 12 months to introduce a cup", "Wean immediately at 6 months", "Use a bottle until age 3"]', 0, 'Prolonged bottle use increases the risk of dental caries and obesity.'),
    (v_topic_id, '37: At what age should iron-fortified solid foods (e.g., cereals, pureed meats) be introduced to a breastfed infant?', '["2 months", "4-6 months", "9 months", "12 months"]', 1, 'Fetal iron stores are depleted by 4-6 months; dietary iron is required to prevent iron deficiency anemia.'),
    (v_topic_id, '38: What is the most common nutritional deficiency in children worldwide?', '["Vitamin A", "Iodine", "Iron", "Zinc"]', 2, 'Iron deficiency is the leading cause of anemia and a major global health issue.'),
    (v_topic_id, '39: A 15-month-old toddler consumes 40 ounces of whole cow''s milk daily and refuses solid foods. What is the most likely consequence?', '["Hypercalcemia", "Iron deficiency anemia", "Vitamin B12 deficiency", "Scurvy"]', 1, 'Excessive cow''s milk (>24 oz/day) causes micro bleeding in the gut and is very low in iron, leading to "milk anemia."'),
    (v_topic_id, '40: What is the AAP recommendation regarding the maximum daily intake of cow''s milk for a toddler (1-3 years old) to prevent iron deficiency?', '["16 ounces", "24 ounces", "32 ounces", "40 ounces"]', 1, 'Limiting milk to 16-24 oz/day encourages the intake of iron-rich solid foods.'),
    (v_topic_id, '41: A child with severe iron deficiency anemia is found chewing on ice, dirt, and paper. This behavior is called:', '["Rumination", "Pica", "Bulimia", "Anorexia"]', 1, 'Pica is a classic, strange craving associated with iron (or zinc) deficiency.'),
    (v_topic_id, '42: Which lab finding is most specific and sensitive for early iron deficiency before anemia develops?', '["Low Hemoglobin", "Low Mean Corpuscular Volume (MCV)", "Low serum Ferritin", "High Total Iron Binding Capacity (TIBC)"]', 2, 'Ferritin reflects total body iron stores and drops before hemoglobin levels fall.'),
    (v_topic_id, '43: A child on total parenteral nutrition (TPN) develops a perioral and perianal rash (acrodermatitis enteropathica), alopecia, and poor wound healing. Deficient nutrient?', '["Iron", "Copper", "Zinc", "Selenium"]', 2, 'Zinc deficiency classically presents with a vesicular/pustular rash around bodily orifices and extremities.'),
    (v_topic_id, '44: An infant with Menkes kinky hair syndrome presents with sparse, brittle hair, hypotonia, and seizures. This is an X-linked recessive defect in the absorption of:', '["Zinc", "Copper", "Iron", "Iodine"]', 1, 'Copper is essential for enzymes like lysyl oxidase (collagen) and tyrosinase (pigment).'),
    (v_topic_id, '45: A child living in a mountainous region develops a large goiter and severe intellectual disability (endemic cretinism). What is the deficient nutrient?', '["Iron", "Selenium", "Iodine", "Fluoride"]', 2, 'Iodine is essential for thyroid hormone synthesis. Deficiency is the leading preventable cause of intellectual disability worldwide.'),
    (v_topic_id, '46: A child presents with cardiomyopathy (Keshan disease). Which trace mineral deficiency is implicated?', '["Zinc", "Copper", "Selenium", "Chromium"]', 2, 'Selenium is an antioxidant; deficiency causes a specific congestive cardiomyopathy.'),
    (v_topic_id, '47: Which trace mineral deficiency is associated with impaired glucose tolerance (a diabetes-like state)?', '["Chromium", "Molybdenum", "Manganese", "Fluoride"]', 0, 'Chromium potentiates the action of insulin.'),
    (v_topic_id, '48: Fluoride is supplemented in municipal water supplies primarily to prevent:', '["Osteoporosis", "Dental caries", "Goiter", "Anemia"]', 1, 'Excess fluoride, however, can cause fluorosis (mottled, discolored teeth).'),
    (v_topic_id, '49: A neonate is diagnosed with Cystic Fibrosis. Which fat-soluble vitamins must be routinely supplemented?', '["Vitamins B and C", "Vitamins A, D, E, K", "Vitamin B12 only", "Folate only"]', 1, 'Pancreatic insufficiency leads to fat malabsorption, causing deficiencies in all fat-soluble vitamins.'),
    (v_topic_id, '50: A full-term, healthy newborn typically requires how many calories per kg per day (kcal/kg/day) for optimal growth?', '["50-60", "80-90", "100-120", "150-180"]', 2, 'Infants require a high caloric density (100-120 kcal/kg/day) to support rapid growth.'),
    (v_topic_id, '51: Standard infant formula (and breast milk) contains approximately how many kilocalories per ounce?', '["10 kcal/oz", "20 kcal/oz", "30 kcal/oz", "40 kcal/oz"]', 1, 'Most standard infant formulas are 20 kcal/oz.'),
    (v_topic_id, '52: Premature infants require higher caloric intake than term infants. What is their typical requirement?', '["100 kcal/kg/day", "120-150 kcal/kg/day", "200 kcal/kg/day", "50 kcal/kg/day"]', 1, 'Premature infants have higher basal metabolic rates and "catch-up" growth requirements.'),
    (v_topic_id, '53: A preterm infant formula is often fortified to provide how many calories per ounce?', '["20 kcal/oz", "22 or 24 kcal/oz", "30 kcal/oz", "40 kcal/oz"]', 1, 'Higher density formulas (22, 24, or even 30 kcal/oz) are used to maximize calories in a small volume for preterm infants.'),
    (v_topic_id, '54: Human milk is ideal for infants. Which of the following is TRUE regarding the composition of human milk compared to cow''s milk?', '["Human milk has higher protein content", "Human milk has a higher whey-to-casein ratio", "Human milk has less lactose", "Human milk has less fat"]', 1, 'Human milk is predominantly whey (easier to digest), while cow''s milk is predominantly casein (forms hard curds).'),
    (v_topic_id, '55: Which immunoglobulin is the predominant antibody found in human breast milk (especially colostrum)?', '["IgG", "IgM", "Secretory IgA", "IgE"]', 2, 'Secretory IgA coats the infant''s gut, providing passive immunity against mucosal pathogens.'),
    (v_topic_id, '56: A mother wishes to breastfeed but is taking medications. Which of the following is an absolute CONTRAINDICATION to breastfeeding in the United States?', '["Hepatitis B surface antigen positivity", "Hepatitis C infection", "HIV infection", "Mastitis"]', 2, 'In developed countries with access to safe formula, HIV is an absolute contraindication to prevent vertical transmission.'),
    (v_topic_id, '57: A mother has active, untreated pulmonary tuberculosis. What is the recommendation regarding breastfeeding?', '["She can breastfeed normally", "The infant can receive expressed breast milk, but direct breastfeeding is contraindicated until the mother is no longer contagious", "Breast milk is strictly contraindicated forever", "The infant must be formula-fed only"]', 1, 'The milk itself does not transmit TB, but the close respiratory contact during feeding is highly contagious.'),
    (v_topic_id, '58: A mother is infected with CMV. Can she breastfeed her healthy full-term infant?', '["Yes", "No", "Only if the milk is pasteurized", "Only after 6 months"]', 0, 'CMV is excreted in breast milk, but healthy term infants are generally unaffected. (It may be contraindicated in very premature/VLBW infants).'),
    (v_topic_id, '59: A 3-week-old infant exclusively breastfed presents with jaundice. Total bilirubin is 12 mg/dL, direct is 0.5 mg/dL. The infant is thriving, feeding well, and gaining weight. Diagnosis?', '["Biliary atresia", "Breast milk jaundice", "Breastfeeding failure jaundice", "Galactosemia"]', 1, 'Breast milk jaundice occurs after the first week of life due to factors in breast milk that inhibit UDP-glucuronosyltransferase. It is benign.'),
    (v_topic_id, '60: A 4-day-old infant exclusively breastfed presents with significant weight loss (12% of birth weight), decreased urine output, and jaundice. Diagnosis?', '["Breast milk jaundice", "Breastfeeding failure jaundice (lactation failure)", "Biliary atresia", "Neonatal hepatitis"]', 1, 'Occurs in the first week due to inadequate milk intake, leading to dehydration and increased enterohepatic circulation of bilirubin.'),
    (v_topic_id, '61: A child with an allergy to cow''s milk protein is switched to a soy-based formula, but still has bloody stools. What is the next best choice of formula?', '["Goat''s milk", "Almond milk", "Extensively hydrolyzed formula", "Lactose-free formula"]', 2, 'Up to 30% of infants with cow''s milk protein allergy cross-react to soy. Extensively hydrolyzed (or amino acid-based) formula is required.'),
    (v_topic_id, '62: An infant is diagnosed with Galactosemia. Which formula is absolutely required?', '["Cow''s milk formula", "Extensively hydrolyzed formula", "Soy-based formula", "Breast milk"]', 2, 'Soy formula is lactose-free and galactose-free, making it the standard of care for classical galactosemia.'),
    (v_topic_id, '63: A 2-year-old child drinks 4 cups of fruit juice daily, eats poorly, and has chronic loose, watery stools without blood. Growth is normal. Diagnosis?', '["Celiac disease", "Toddler''s diarrhea (Chronic nonspecific diarrhea)", "Cystic fibrosis", "Inflammatory bowel disease"]', 1, 'Excessive juice (sorbitol/fructose) causes osmotic diarrhea. Treatment is reducing juice intake and increasing dietary fat.'),
    (v_topic_id, '64: A teenager restricts her caloric intake to 500 kcal/day, exercises obsessively, and has a BMI of 15. She intensely fears gaining weight and denies being too thin. Diagnosis?', '["Bulimia nervosa", "Anorexia nervosa", "Binge eating disorder", "Hyperthyroidism"]', 1, 'Anorexia nervosa is characterized by significantly low body weight, intense fear of weight gain, and body dysmorphia.'),
    (v_topic_id, '65: Which of the following is a classic physical exam finding in severe Anorexia Nervosa?', '["Tachycardia and hypertension", "Lanugo (fine, downy hair on the body)", "Exophthalmos", "Acanthosis nigricans"]', 1, 'Lanugo is a physiologic response to conserve heat due to severe loss of insulating body fat.'),
    (v_topic_id, '66: A patient with Anorexia Nervosa frequently purges by vomiting. What electrolyte abnormality is expected?', '["Hyperkalemic hyperchloremic acidosis", "Hypokalemic hypochloremic metabolic alkalosis", "Hypernatremia", "Hypocalcemia"]', 1, 'Vomiting causes loss of gastric acid (HCl) and potassium, leading to a metabolic alkalosis.'),
    (v_topic_id, '67: What physical exam finding on the hands is suggestive of self-induced vomiting (Bulimia or purging-type Anorexia)?', '["Koilonychia (spoon nails)", "Clubbing", "Russell sign (calluses on the knuckles)", "Osler nodes"]', 2, 'Repeated friction of the knuckles against the upper teeth causes these calluses.'),
    (v_topic_id, '68: What is a major cardiac complication and common cause of sudden death in patients with severe Anorexia Nervosa?', '["Aortic dissection", "Prolonged QTc interval leading to arrhythmias", "Myocardial infarction", "Endocarditis"]', 1, 'Electrolyte abnormalities (hypokalemia) and severe starvation can prolong the QTc interval.'),
    (v_topic_id, '69: A 6-year-old child refuses to eat foods with certain textures or colors (e.g., nothing "crunchy" or "green"), leading to weight loss and nutritional deficiency. The child has no body image distortion. Diagnosis?', '["Anorexia nervosa", "Avoidant/Restrictive Food Intake Disorder (ARFID)", "Bulimia nervosa", "Normal picky eating"]', 1, 'ARFID involves a lack of interest in eating or avoidance based on sensory characteristics, distinct from the body dysmorphia of anorexia.'),
    (v_topic_id, '70: A child with obesity (BMI >95th percentile) presents with darkened, velvety, thickened skin on the back of the neck and axillae. What does this indicate?', '["Poor hygiene", "Addison disease", "Insulin resistance (Acanthosis nigricans)", "Pellagra"]', 2, 'Acanthosis nigricans is a key physical marker for hyperinsulinemia and risk of Type 2 Diabetes.'),
    (v_topic_id, '71: What is the most common cause of hypertension in the pediatric population?', '["Renal artery stenosis", "Coarctation of the aorta", "Primary (essential) hypertension linked to obesity", "Pheochromocytoma"]', 2, 'With the rise in pediatric obesity, primary hypertension is now the leading cause, surpassing secondary renal causes.'),
    (v_topic_id, '72: A 12-year-old obese boy complains of a dull ache in his left knee and a limp. He has limited internal rotation of the left hip. Diagnosis?', '["Osgood-Schlatter disease", "Legg-Calve-Perthes disease", "Slipped Capital Femoral Epiphysis (SCFE)", "Septic arthritis"]', 2, 'SCFE is strongly associated with obesity and adolescence; the femoral head slips posteriorly and inferiorly.'),
    (v_topic_id, '73: A 10-year-old obese girl presents with snoring, witnessed pauses in breathing during sleep, and daytime sleepiness. Diagnosis?', '["Narcolepsy", "Obstructive Sleep Apnea (OSA)", "Asthma", "Central sleep apnea"]', 1, 'Obesity is a major risk factor for pediatric OSA, alongside adenotonsillar hypertrophy.'),
    (v_topic_id, '74: The AAP recommends that children aged 2 years and older should consume a diet where saturated fat is less than what percentage of total calories?', '["5%", "10%", "20%", "30%"]', 1, 'Limiting saturated fat to <10% of total calories helps prevent dyslipidemia and cardiovascular disease.'),
    (v_topic_id, '75: A child on a long-term ketogenic diet for intractable epilepsy is at increased risk for which nutritional deficiency?', '["Vitamin C", "Calcium and Vitamin D", "Iron", "Zinc"]', 1, 'The highly restrictive nature of the diet often requires supplementation of calcium, vitamin D, and multivitamins to prevent osteopenia.'),
    (v_topic_id, '76: A 2-month-old infant has projectile, non-bilious vomiting after every feed. The infant is always hungry. Blood gas shows hypochloremic metabolic alkalosis. What is the most appropriate initial management?', '["Immediate surgery (pyloromyotomy)", "IV fluid resuscitation and electrolyte correction", "Start proton pump inhibitors", "Change formula to soy"]', 1, 'Correction of the alkalosis and dehydration (with normal saline) is mandatory BEFORE surgical correction of pyloric stenosis to prevent apnea from anesthesia.'),
    (v_topic_id, '77: A child with short bowel syndrome (e.g., after extensive resection for necrotizing enterocolitis) depends on TPN. What is the most severe long-term complication of prolonged TPN use?', '["Hypoglycemia", "TPN-associated cholestasis and liver failure", "Renal failure", "Heart failure"]', 1, 'Lack of enteral feeding prevents gallbladder emptying, leading to biliary stasis, cholestasis, and eventually cirrhosis.'),
    (v_topic_id, '78: To prevent TPN-associated liver disease in a child with short bowel syndrome, what intervention is crucial?', '["Increase IV lipids", "Start high-dose steroids", "Initiate minimal enteral ''trophic'' feeds as early as possible", "Perform a liver biopsy"]', 2, 'Even tiny amounts of enteral feeding stimulate gut hormones (CCK) and maintain gut mucosal integrity, reducing cholestasis.'),
    (v_topic_id, '79: A 1-year-old child presents with a distended abdomen, thin extremities, and sparse hair. Blood tests reveal severe hypoalbuminemia. Which form of severe acute malnutrition (SAM) is this?', '["Marasmus", "Kwashiorkor", "Scurvy", "Pellagra"]', 1, 'Hypoalbuminemia is the driving force behind the edema/ascites seen in Kwashiorkor.'),
    (v_topic_id, '80: A vegan mother is weaning her 1-year-old. She plans to use almond milk as the primary beverage. What is the main concern?', '["Too much fat", "Inadequate protein and calcium density compared to cow''s/soy milk", "Too much iron", "Risk of galactosemia"]', 1, 'Plant-based milks (except fortified soy) often lack the protein and caloric density required for a growing toddler.'),
    (v_topic_id, '81: A child with "Failure to Thrive" is noted to cross percentiles downwards around 6 months of age, just as solid foods (cereals) were introduced. They have chronic diarrhea. Most likely diagnosis?', '["Cystic fibrosis", "Celiac disease", "Pyloric stenosis", "Iron deficiency"]', 1, 'The timing of symptoms correlating with the introduction of gluten (wheat cereals) is highly suspicious for Celiac disease.'),
    (v_topic_id, '82: A child is diagnosed with lactose intolerance. What is the underlying pathophysiology?', '["Autoimmune destruction of the small intestine", "IgE-mediated allergy to milk proteins", "Deficiency of the brush border enzyme lactase", "Pancreatic insufficiency"]', 2, 'Lactase deficiency leads to unabsorbed lactose in the gut, causing osmotic diarrhea and gas production by colonic bacteria.'),
    (v_topic_id, '83: A 3-week-old infant has bloody streaks in the stool. They are exclusively formula-fed. They are fussy but gaining weight normally. Most likely diagnosis?', '["Intussusception", "Cow''s milk protein allergy (allergic proctocolitis)", "Necrotizing enterocolitis", "Meckel diverticulum"]', 1, 'A common, benign condition. The treatment is switching to an extensively hydrolyzed formula. (If breastfed, mother restricts dairy).'),
    (v_topic_id, '84: In an infant with cow''s milk protein allergy, at what age does the condition typically resolve?', '["6 months", "By 1 year of age (most outgrow it)", "It is a lifelong allergy", "10 years"]', 1, 'Unlike IgE-mediated peanut allergies, milk protein proctocolitis is usually outgrown by 12 months.'),
    (v_topic_id, '85: A child has a severe, anaphylactic reaction (hives, wheezing, hypotension) immediately after eating peanut butter. This is mediated by:', '["IgG", "IgM", "IgE", "T-cells"]', 2, 'Anaphylaxis is a Type I hypersensitivity reaction, which is IgE-mediated and involves mast cell degranulation.'),
    (v_topic_id, '86: What is the recommended AAP guidance on the introduction of highly allergenic foods (like peanuts) to infants?', '["Delay until 3 years of age", "Delay until 1 year of age", "Early introduction (around 4-6 months) to high-risk infants to induce tolerance", "Never give peanuts to children under 5"]', 2, 'The LEAP study showed that early introduction of peanuts in high-risk infants actually prevents the development of the allergy.'),
    (v_topic_id, '87: A neonate has a meconium ileus. Which vitamin deficiency are they immediately at risk for if untreated?', '["Vitamin B1", "Vitamin C", "Vitamin K", "Folate"]', 2, 'Meconium ileus implies Cystic Fibrosis. Fat malabsorption leads to Vitamin K deficiency, causing bleeding risks.'),
    (v_topic_id, '88: Which of the following is a normal, physiologic reason for a toddler (age 2) to eat significantly less than they did as an infant?', '["Depression", "Physiologic anorexia due to a normal decrease in growth velocity", "Celiac disease", "Gastroparesis"]', 1, 'Growth slows dramatically after the first year, so caloric needs (and appetite) decrease proportionally. This often worries parents.'),
    (v_topic_id, '89: A child is admitted with anorexia nervosa. Their heart rate is 38 bpm. What is the most appropriate management?', '["Pacemaker insertion", "Administer atropine", "Admit to telemetry and begin slow, controlled refeeding", "Administer epinephrine"]', 2, 'Bradycardia is a physiologic adaptation to starvation. It resolves with careful refeeding. Atropine is rarely needed unless hemodynamically unstable.'),
    (v_topic_id, '90: Which screening tool is commonly used to assess weight status in children aged 2 and older?', '["Weight for length", "BMI percentile for age and sex", "Absolute BMI number (like in adults)", "Ponderal index"]', 1, 'BMI in children must be plotted on a percentile chart because normal BMI changes significantly with age and gender.'),
    (v_topic_id, '91: A child has a BMI at the 88th percentile. What is the classification?', '["Healthy weight", "Overweight", "Obese", "Severely obese"]', 1, '85th to <95th percentile is Overweight. >=95th is Obese.'),
    (v_topic_id, '92: A child has a BMI at the 97th percentile. What is the classification?', '["Healthy weight", "Overweight", "Obese", "Severely obese"]', 2, 'BMI >= 95th percentile defines obesity in children.'),
    (v_topic_id, '93: The mother of a 4-month-old asks if she should give her baby water on a hot day. The baby is exclusively formula-fed. Advice?', '["Yes, up to 8 oz a day", "No, infant formula provides adequate hydration; extra free water risks hyponatremia and seizures", "Yes, but mix it with salt", "Only if the baby looks sweaty"]', 1, 'Infants kidneys cannot handle large free water loads, leading to dangerous water intoxication.'),
    (v_topic_id, '94: Which condition requires an infant to be fed a formula free of both phenylalanine and tyrosine?', '["PKU", "Tyrosinemia", "Alkaptonuria", "None, PKU formula restricts phenylalanine but must supply tyrosine"]', 3, 'In PKU, tyrosine becomes an essential amino acid because it cannot be synthesized from phenylalanine.'),
    (v_topic_id, '95: A child presents with alopecia, a scaly erythematous rash, and frequent infections. They consume a large amount of raw egg whites. Deficient nutrient?', '["Biotin (Vitamin B7)", "Vitamin C", "Vitamin A", "Zinc"]', 0, 'Raw egg whites contain avidin, which tightly binds biotin and prevents its absorption.'),
    (v_topic_id, '96: A toddler is found to have a lead level of 15 mcg/dL. Which nutritional deficiency increases the absorption of lead from the GI tract?', '["Vitamin C", "Iron", "Vitamin D", "Folate"]', 1, 'Iron deficiency upregulates DMT1 transporters in the gut, which inadvertently increases the absorption of heavy metals like lead.'),
    (v_topic_id, '97: A child has "spoon-shaped" nails (koilonychia). This is a physical sign of which chronic deficiency?', '["Vitamin A", "Iron", "Vitamin C", "Zinc"]', 1, 'Koilonychia is a classic sign of chronic, severe iron deficiency anemia.'),
    (v_topic_id, '98: Which vitamin is highly teratogenic in excessive doses during early pregnancy?', '["Vitamin C", "Vitamin B12", "Vitamin A", "Folate"]', 2, 'Isotretinoin (a Vitamin A derivative) causes severe craniofacial and cardiac defects.'),
    (v_topic_id, '99: A child with a history of bowel resection for necrotizing enterocolitis has a large segment of the terminal ileum removed. Which vitamin deficiency are they guaranteed to develop without supplementation?', '["Vitamin C", "Vitamin B12", "Folate", "Vitamin A"]', 1, 'Vitamin B12 is absorbed exclusively in the terminal ileum (bound to intrinsic factor).'),
    (v_topic_id, '100: Final Pearl: When evaluating a child for Failure to Thrive, what is the most important FIRST step before ordering extensive lab tests?', '["Order a head CT", "Obtain a thorough dietary history, feeding observation, and plot growth curves accurately", "Order a genetic microarray", "Perform an endoscopy"]', 1, 'A detailed history (including formula mixing, daily caloric intake, and psychosocial stressors) identifies the cause of FTT in the vast majority of cases without invasive testing.');
